// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IVaultToken {
    function balanceOf(address account) external view returns (uint256);
}

/// @title GanymedeBasketVault
/// @notice A basket token backed by its constituents and created and redeemed in kind, the way an
///         ETF's authorized participants deliver and receive the underlying shares. The first
///         creation takes a fixed quantity of each constituent per share, set at deployment. After
///         that every share is an equal claim on everything the vault holds: creating shares
///         delivers each constituent in proportion to the holdings, and redeeming pays each out in
///         proportion. The vault prices nothing and has no owner, so no one can mint shares without
///         the tokens or move the tokens without burning shares.
/// @dev Shares have 6 decimals. xStocks keep balances as shares times a multiplier: a transfer can
///      arrive a base unit short (on a fork of X Layer mainnet, sending 10^18 AAPLx delivered
///      10^18 − 1), and a dividend, split or fee paid through the multiplier changes every balance.
///      Proportional creation and redemption pass such changes to the shares instead of stranding
///      them or leaving the vault short. Creation takes the proportional amount rounded up plus
///      ROUNDING_ALLOWANCE and refuses a call in which any token arrives short of the proportional
///      amount, so a fee-on-transfer token cannot dilute holders; redemption pays the proportional
///      amount rounded down less ROUNDING_ALLOWANCE. The first creation must be at least one whole
///      share, and every creation names the most of each token it will deliver, so no one can make
///      shares expensive by creating a dust share and donating to the vault. Not deployed: it runs
///      against the real xStocks on a fork of X Layer mainnet (npm run fork:vault).
contract GanymedeBasketVault {
    uint8 public constant decimals = 6;
    uint256 public constant SHARE = 1e6;
    uint256 public constant MAX_TOKENS = 20;
    /// @notice Base units added to each creation and kept from each redemption, per token.
    uint256 public constant ROUNDING_ALLOWANCE = 4;

    string public name;
    string public symbol;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    address[] private _tokens;
    /// @dev Token base units per whole share (10^6 share units) for the first creation, one per token.
    uint256[] private _initialUnits;
    uint256 private _locked = 1;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Created(address indexed account, uint256 shares, uint256[] amounts);
    event Redeemed(address indexed account, uint256 shares, uint256[] amounts);

    error InvalidBasket();
    error InvalidAmount();
    error InsufficientBalance();
    error InsufficientAllowance();
    error TransferFailed();
    error ExceedsMaximum();
    error Reentrancy();

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    constructor(string memory name_, string memory symbol_, address[] memory tokens_, uint256[] memory initialUnits_) {
        uint256 count = tokens_.length;
        if (count == 0 || count > MAX_TOKENS || initialUnits_.length != count) revert InvalidBasket();
        for (uint256 i = 0; i < count; i++) {
            if (tokens_[i] == address(0) || tokens_[i].code.length == 0 || initialUnits_[i] == 0) revert InvalidBasket();
            for (uint256 j = 0; j < i; j++) if (tokens_[j] == tokens_[i]) revert InvalidBasket();
        }
        name = name_;
        symbol = symbol_;
        _tokens = tokens_;
        _initialUnits = initialUnits_;
    }

    function tokens() external view returns (address[] memory) {
        return _tokens;
    }

    function initialUnits() external view returns (uint256[] memory) {
        return _initialUnits;
    }

    /// @notice What one whole share holds of each token now: the initial units before any shares exist.
    function holdingsPerShare() external view returns (uint256[] memory units) {
        units = new uint256[](_tokens.length);
        for (uint256 i = 0; i < _tokens.length; i++) {
            units[i] = totalSupply == 0 ? _initialUnits[i] : (IVaultToken(_tokens[i]).balanceOf(address(this)) * SHARE) / totalSupply;
        }
    }

    /// @notice The proportional amount of each token behind `shares` (rounded up), what creating them
    ///         takes (that plus ROUNDING_ALLOWANCE) and what redeeming them pays.
    function amountsFor(uint256 shares) public view returns (uint256[] memory owed, uint256[] memory createIn, uint256[] memory redeemOut) {
        uint256 count = _tokens.length;
        owed = new uint256[](count);
        createIn = new uint256[](count);
        redeemOut = new uint256[](count);
        uint256 supply = totalSupply;
        for (uint256 i = 0; i < count; i++) {
            (uint256 numerator, uint256 denominator) = supply == 0
                ? (_initialUnits[i] * shares, SHARE)
                : (IVaultToken(_tokens[i]).balanceOf(address(this)) * shares, supply);
            uint256 exact = numerator / denominator;
            owed[i] = exact + (numerator % denominator == 0 ? 0 : 1);
            createIn[i] = owed[i] + ROUNDING_ALLOWANCE;
            redeemOut[i] = supply == 0 || shares > supply ? 0 : (exact > ROUNDING_ALLOWANCE ? exact - ROUNDING_ALLOWANCE : 0);
        }
    }

    /// @notice Delivers each constituent's share of the holdings for `shares` (approve each token
    ///         first) and mints the shares. `maxAmounts` is the most of each token the caller will
    ///         deliver, in token order, as `amountsFor` quotes it.
    function create(uint256 shares, uint256[] calldata maxAmounts) external nonReentrant returns (uint256[] memory amounts) {
        if (shares == 0 || (totalSupply == 0 && shares < SHARE)) revert InvalidAmount();
        if (maxAmounts.length != _tokens.length) revert InvalidAmount();
        uint256[] memory owed;
        (owed, amounts, ) = amountsFor(shares);
        for (uint256 i = 0; i < amounts.length; i++) if (amounts[i] > maxAmounts[i]) revert ExceedsMaximum();
        for (uint256 i = 0; i < amounts.length; i++) {
            address token = _tokens[i];
            uint256 before = IVaultToken(token).balanceOf(address(this));
            _call(token, abi.encodeWithSelector(0x23b872dd, msg.sender, address(this), amounts[i])); // transferFrom
            if (IVaultToken(token).balanceOf(address(this)) - before < owed[i]) revert TransferFailed();
        }
        totalSupply += shares;
        balanceOf[msg.sender] += shares;
        emit Transfer(address(0), msg.sender, shares);
        emit Created(msg.sender, shares, amounts);
    }

    /// @notice Burns `shares` and pays the caller their share of every constituent.
    function redeem(uint256 shares) external nonReentrant returns (uint256[] memory amounts) {
        if (shares == 0) revert InvalidAmount();
        if (balanceOf[msg.sender] < shares) revert InsufficientBalance();
        (, , amounts) = amountsFor(shares);
        balanceOf[msg.sender] -= shares;
        totalSupply -= shares;
        emit Transfer(msg.sender, address(0), shares);
        for (uint256 i = 0; i < amounts.length; i++) {
            if (amounts[i] > 0) _call(_tokens[i], abi.encodeWithSelector(0xa9059cbb, msg.sender, amounts[i])); // transfer
        }
        emit Redeemed(msg.sender, shares, amounts);
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function approve(address spender, uint256 value) external returns (bool) {
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 allowed = allowance[from][msg.sender];
        if (allowed != type(uint256).max) {
            if (allowed < value) revert InsufficientAllowance();
            allowance[from][msg.sender] = allowed - value;
        }
        _transfer(from, to, value);
        return true;
    }

    function _transfer(address from, address to, uint256 value) private {
        if (from == address(0) || to == address(0) || to == address(this)) revert InvalidAmount();
        if (balanceOf[from] < value) revert InsufficientBalance();
        balanceOf[from] -= value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    /// @dev Accepts tokens that return true or nothing, like OpenZeppelin's SafeERC20.
    function _call(address token, bytes memory data) private {
        (bool ok, bytes memory result) = token.call(data);
        if (!ok || (result.length != 0 && !abi.decode(result, (bool)))) revert TransferFailed();
    }
}

contracts/GanymedeDemoDollar.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title GanymedeDemoDollar
/// @notice Demo dollars for the Ganymede app on X Layer Testnet. They have no value.
///         Anyone can claim a fixed amount once a day; beyond that, only the fund
///         contract (the minter) issues them, when it pays out a redemption.
contract GanymedeDemoDollar {
    string public constant name = "Ganymede Demo Dollar";
    string public constant symbol = "dUSD";
    uint8 public constant decimals = 6;

    uint256 public constant CLAIM_AMOUNT = 10_000 * 10 ** 6;
    uint256 public constant CLAIM_INTERVAL = 1 days;

    uint256 public totalSupply;
    address public administrator;
    address public pendingAdministrator;
    address public minter;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => uint256) public lastClaimAt;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Claimed(address indexed account, uint256 amount);
    event MinterChanged(address indexed previousMinter, address indexed newMinter);
    event AdministratorProposed(address indexed currentAdministrator, address indexed pendingAdministrator);
    event AdministratorAccepted(address indexed previousAdministrator, address indexed newAdministrator);

    error Unauthorized();
    error InvalidAddress();
    error InsufficientBalance();
    error InsufficientAllowance();
    error ClaimTooSoon(uint256 nextClaimAt);

    modifier onlyAdministrator() {
        if (msg.sender != administrator) revert Unauthorized();
        _;
    }

    constructor(address initialAdministrator) {
        if (initialAdministrator == address(0)) revert InvalidAddress();
        administrator = initialAdministrator;
    }

    /// @notice Sends CLAIM_AMOUNT demo dollars to the caller, at most once per CLAIM_INTERVAL.
    function claim() external {
        uint256 next = nextClaimAt(msg.sender);
        if (block.timestamp < next) revert ClaimTooSoon(next);
        lastClaimAt[msg.sender] = block.timestamp;
        _mint(msg.sender, CLAIM_AMOUNT);
        emit Claimed(msg.sender, CLAIM_AMOUNT);
    }

    /// @notice The earliest time `account` can claim again; 0 when it never claimed.
    function nextClaimAt(address account) public view returns (uint256) {
        uint256 last = lastClaimAt[account];
        return last == 0 ? 0 : last + CLAIM_INTERVAL;
    }

    function mint(address to, uint256 value) external {
        if (msg.sender != minter) revert Unauthorized();
        _mint(to, value);
    }

    /// @notice Burns the caller's own demo dollars.
    function burn(uint256 value) external {
        uint256 balance = balanceOf[msg.sender];
        if (balance < value) revert InsufficientBalance();
        balanceOf[msg.sender] = balance - value;
        totalSupply -= value;
        emit Transfer(msg.sender, address(0), value);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        if (spender == address(0)) revert InvalidAddress();
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        uint256 available = allowance[from][msg.sender];
        if (available < value) revert InsufficientAllowance();
        if (available != type(uint256).max) {
            allowance[from][msg.sender] = available - value;
            emit Approval(from, msg.sender, available - value);
        }
        _transfer(from, to, value);
        return true;
    }

    function setMinter(address newMinter) external onlyAdministrator {
        if (newMinter == address(0)) revert InvalidAddress();
        emit MinterChanged(minter, newMinter);
        minter = newMinter;
    }

    function proposeAdministrator(address nextAdministrator) external onlyAdministrator {
        if (nextAdministrator == address(0)) revert InvalidAddress();
        pendingAdministrator = nextAdministrator;
        emit AdministratorProposed(administrator, nextAdministrator);
    }

    function acceptAdministrator() external {
        if (msg.sender != pendingAdministrator) revert Unauthorized();
        address previous = administrator;
        administrator = msg.sender;
        pendingAdministrator = address(0);
        emit AdministratorAccepted(previous, msg.sender);
    }

    function _mint(address to, uint256 value) internal {
        if (to == address(0)) revert InvalidAddress();
        totalSupply += value;
        balanceOf[to] += value;
        emit Transfer(address(0), to, value);
    }

    function _transfer(address from, address to, uint256 value) internal {
        if (to == address(0)) revert InvalidAddress();
        uint256 balance = balanceOf[from];
        if (balance < value) revert InsufficientBalance();
        balanceOf[from] = balance - value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }
}

contracts/GanymedeFundShare.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title GanymedeFundShare
/// @notice Restricted-transfer fund share ledger for GIWA settlement.
/// @dev Administration and issuance roles should be controlled by independent multisigs.
contract GanymedeFundShare {
    string public name;
    string public symbol;
    uint8 public constant decimals = 6;

    uint256 public totalSupply;
    address public administrator;
    address public pendingAdministrator;
    address public issuer;
    address public transferAgent;
    bool public paused;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;
    mapping(address => bool) public isAllowed;
    mapping(bytes32 => bool) public processedSettlement;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event InvestorPermission(address indexed investor, bool allowed);
    event SubscriptionSettled(bytes32 indexed settlementId, address indexed investor, uint256 shares);
    event RedemptionSettled(bytes32 indexed settlementId, address indexed investor, uint256 shares);
    event IssuerChanged(address indexed previousIssuer, address indexed newIssuer);
    event TransferAgentChanged(address indexed previousAgent, address indexed newAgent);
    event AdministratorProposed(address indexed currentAdministrator, address indexed pendingAdministrator);
    event AdministratorAccepted(address indexed previousAdministrator, address indexed newAdministrator);
    event Paused(address indexed account);
    event Unpaused(address indexed account);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error TransferRestricted();
    error ContractPaused();
    error SettlementAlreadyProcessed();
    error InsufficientBalance();
    error InsufficientAllowance();

    modifier onlyAdministrator() {
        if (msg.sender != administrator) revert Unauthorized();
        _;
    }

    modifier onlyIssuer() {
        if (msg.sender != issuer) revert Unauthorized();
        _;
    }

    modifier onlyTransferAgentOrAdministrator() {
        if (msg.sender != transferAgent && msg.sender != administrator) revert Unauthorized();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert ContractPaused();
        _;
    }

    constructor(string memory fundName, string memory fundSymbol, address initialAdministrator) {
        if (initialAdministrator == address(0)) revert InvalidAddress();
        name = fundName;
        symbol = fundSymbol;
        administrator = initialAdministrator;
        issuer = initialAdministrator;
        transferAgent = initialAdministrator;
        isAllowed[initialAdministrator] = true;
        emit InvestorPermission(initialAdministrator, true);
    }

    function approve(address spender, uint256 value) external returns (bool) {
        if (spender == address(0)) revert InvalidAddress();
        allowance[msg.sender][spender] = value;
        emit Approval(msg.sender, spender, value);
        return true;
    }

    function transfer(address to, uint256 value) external whenNotPaused returns (bool) {
        _transfer(msg.sender, to, value);
        return true;
    }

    function transferFrom(address from, address to, uint256 value) external whenNotPaused returns (bool) {
        uint256 available = allowance[from][msg.sender];
        if (available < value) revert InsufficientAllowance();
        if (available != type(uint256).max) {
            allowance[from][msg.sender] = available - value;
            emit Approval(from, msg.sender, available - value);
        }
        _transfer(from, to, value);
        return true;
    }

    function settleSubscription(bytes32 settlementId, address investor, uint256 shares) external onlyIssuer whenNotPaused {
        if (investor == address(0)) revert InvalidAddress();
        if (!isAllowed[investor]) revert TransferRestricted();
        if (shares == 0) revert InvalidAmount();
        _consumeSettlement(settlementId);
        totalSupply += shares;
        balanceOf[investor] += shares;
        emit Transfer(address(0), investor, shares);
        emit SubscriptionSettled(settlementId, investor, shares);
    }

    function settleRedemption(bytes32 settlementId, address investor, uint256 shares) external onlyIssuer whenNotPaused {
        if (shares == 0) revert InvalidAmount();
        _consumeSettlement(settlementId);
        uint256 balance = balanceOf[investor];
        if (balance < shares) revert InsufficientBalance();
        balanceOf[investor] = balance - shares;
        totalSupply -= shares;
        emit Transfer(investor, address(0), shares);
        emit RedemptionSettled(settlementId, investor, shares);
    }

    function setInvestorPermission(address investor, bool allowed) external onlyTransferAgentOrAdministrator {
        if (investor == address(0)) revert InvalidAddress();
        isAllowed[investor] = allowed;
        emit InvestorPermission(investor, allowed);
    }

    function setInvestorPermissions(address[] calldata investors, bool allowed) external onlyTransferAgentOrAdministrator {
        for (uint256 index = 0; index < investors.length; index++) {
            address investor = investors[index];
            if (investor == address(0)) revert InvalidAddress();
            isAllowed[investor] = allowed;
            emit InvestorPermission(investor, allowed);
        }
    }

    function setIssuer(address newIssuer) external onlyAdministrator {
        if (newIssuer == address(0)) revert InvalidAddress();
        emit IssuerChanged(issuer, newIssuer);
        issuer = newIssuer;
    }

    function setTransferAgent(address newTransferAgent) external onlyAdministrator {
        if (newTransferAgent == address(0)) revert InvalidAddress();
        emit TransferAgentChanged(transferAgent, newTransferAgent);
        transferAgent = newTransferAgent;
    }

    function pause() external onlyAdministrator {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyAdministrator {
        paused = false;
        emit Unpaused(msg.sender);
    }

    function proposeAdministrator(address nextAdministrator) external onlyAdministrator {
        if (nextAdministrator == address(0)) revert InvalidAddress();
        pendingAdministrator = nextAdministrator;
        emit AdministratorProposed(administrator, nextAdministrator);
    }

    function acceptAdministrator() external {
        if (msg.sender != pendingAdministrator) revert Unauthorized();
        address previous = administrator;
        administrator = msg.sender;
        pendingAdministrator = address(0);
        isAllowed[msg.sender] = true;
        emit AdministratorAccepted(previous, msg.sender);
        emit InvestorPermission(msg.sender, true);
    }

    function _transfer(address from, address to, uint256 value) internal {
        if (to == address(0)) revert InvalidAddress();
        if (!isAllowed[from] || !isAllowed[to]) revert TransferRestricted();
        uint256 balance = balanceOf[from];
        if (balance < value) revert InsufficientBalance();
        balanceOf[from] = balance - value;
        balanceOf[to] += value;
        emit Transfer(from, to, value);
    }

    function _consumeSettlement(bytes32 settlementId) internal {
        if (settlementId == bytes32(0)) revert InvalidAmount();
        if (processedSettlement[settlementId]) revert SettlementAlreadyProcessed();
        processedSettlement[settlementId] = true;
    }
}

contracts/GanymedeLendingMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IMarketDollar {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IMarketFund {
    function dollar() external view returns (address);
    function currentNav() external view returns (uint256 navPerShareMicros, uint64 effectiveAt);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

/// @title GanymedeLendingMarket
/// @notice Demo-dollar loans against USTX on X Layer Testnet. Lenders supply dUSD and earn the
///         interest borrowers pay. Borrowers post USTX, valued at the NAV the fund trades at, and
///         borrow dUSD against it. When a loan grows past LIQUIDATION_THRESHOLD of its collateral
///         value, anyone can repay part of it and take USTX at a discount, which the fund redeems
///         at NAV.
/// @dev Starts paused: nothing can be supplied or borrowed until the administrator unpauses it.
///      Pausing never blocks repaying, withdrawing or liquidating. Debt left after all of a
///      borrower's collateral is seized stays on that account; there is no bad-debt auction.
///      Amounts are in micros (6 decimals, like dUSD and USTX); indices, rates and factors are
///      scaled by 1e18. Rounding always favours the market.
contract GanymedeLendingMarket {
    uint256 private constant WAD = 1e18;
    uint256 private constant ONE_SHARE = 1e6;
    uint256 public constant SECONDS_PER_YEAR = 365 days;

    uint256 public constant BORROW_COLLATERAL_FACTOR = 0.50e18;
    uint256 public constant LIQUIDATION_THRESHOLD = 0.65e18;
    uint256 public constant LIQUIDATION_BONUS = 0.08e18;
    uint256 public constant CLOSE_FACTOR = 0.50e18;
    uint256 public constant RESERVE_FACTOR = 0.10e18;
    uint256 public constant MIN_BORROW = 10 * 10 ** 6;

    // Borrow rate per year: BASE + MULTIPLIER × utilization up to KINK, then JUMP_MULTIPLIER above it.
    uint256 public constant BASE_RATE_PER_YEAR = 0.02e18;
    uint256 public constant MULTIPLIER_PER_YEAR = 0.10e18;
    uint256 public constant JUMP_MULTIPLIER_PER_YEAR = 2e18;
    uint256 public constant KINK = 0.80e18;

    IMarketDollar public immutable dollar;
    IMarketFund public immutable fund;

    uint256 public supplyIndex;
    uint256 public borrowIndex;
    uint256 public lastAccrualTime;
    uint256 public totalSupplyPrincipal;
    uint256 public totalBorrowPrincipal;
    uint256 public totalCollateral;

    mapping(address => uint256) public supplyPrincipalOf;
    mapping(address => uint256) public borrowPrincipalOf;
    mapping(address => uint256) public collateralOf;

    address public administrator;
    address public pendingAdministrator;
    bool public paused;

    event Supplied(address indexed account, uint256 amount);
    event Withdrawn(address indexed account, uint256 amount);
    event CollateralSupplied(address indexed account, uint256 shares);
    event CollateralWithdrawn(address indexed account, uint256 shares);
    event Borrowed(address indexed account, uint256 amount);
    event Repaid(address indexed account, uint256 amount);
    event Liquidated(address indexed liquidator, address indexed borrower, uint256 repaid, uint256 seized, uint256 navPerShareMicros);
    event AdministratorProposed(address indexed currentAdministrator, address indexed pendingAdministrator);
    event AdministratorAccepted(address indexed previousAdministrator, address indexed newAdministrator);
    event Paused(address indexed account);
    event Unpaused(address indexed account);

    error Unauthorized();
    error InvalidAddress();
    error InvalidAmount();
    error BelowMinimum();
    error InsufficientBalance();
    error InsufficientLiquidity();
    error InsufficientCollateral();
    error NotLiquidatable();
    error SlippageExceeded();
    error TransferFailed();
    error ContractPaused();

    modifier onlyAdministrator() {
        if (msg.sender != administrator) revert Unauthorized();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert ContractPaused();
        _;
    }

    constructor(address demoDollar, address basketFund, address initialAdministrator) {
        if (demoDollar == address(0) || basketFund == address(0) || initialAdministrator == address(0)) revert InvalidAddress();
        // Loans are in the dollar the fund redeems into, so seized USTX can always be sold back.
        if (IMarketFund(basketFund).dollar() != demoDollar) revert InvalidAddress();
        dollar = IMarketDollar(demoDollar);
        fund = IMarketFund(basketFund);
        administrator = initialAdministrator;
        supplyIndex = WAD;
        borrowIndex = WAD;
        lastAccrualTime = block.timestamp;
        paused = true;
    }

    // ---- Lenders ----

    /// @notice Lends `amount` dUSD (approved to this market). It earns interest from borrowers.
    function supply(uint256 amount) external whenNotPaused {
        accrueInterest();
        uint256 principal = amount * WAD / supplyIndex;
        if (principal == 0) revert InvalidAmount();
        supplyPrincipalOf[msg.sender] += principal;
        totalSupplyPrincipal += principal;
        _receiveDollars(msg.sender, amount);
        emit Supplied(msg.sender, amount);
    }

    /// @notice Withdraws lent dUSD with its interest; `type(uint256).max` withdraws all of it.
    function withdraw(uint256 amount) external returns (uint256 withdrawn) {
        accrueInterest();
        uint256 principal = supplyPrincipalOf[msg.sender];
        uint256 balance = principal * supplyIndex / WAD;
        uint256 burned;
        if (amount == type(uint256).max) {
            (withdrawn, burned) = (balance, principal);
        } else {
            if (amount > balance) revert InsufficientBalance();
            (withdrawn, burned) = (amount, _ceilDiv(amount * WAD, supplyIndex));
        }
        if (withdrawn == 0) revert InvalidAmount();
        if (withdrawn > cash()) revert InsufficientLiquidity();
        supplyPrincipalOf[msg.sender] = principal - burned;
        totalSupplyPrincipal -= burned;
        _sendDollars(msg.sender, withdrawn);
        emit Withdrawn(msg.sender, withdrawn);
    }

    // ---- Borrowers ----

    /// @notice Posts `shares` USTX (approved to this market) as collateral.
    function supplyCollateral(uint256 shares) external whenNotPaused {
        if (shares == 0) revert InvalidAmount();
        collateralOf[msg.sender] += shares;
        totalCollateral += shares;
        _receiveShares(msg.sender, shares);
        emit CollateralSupplied(msg.sender, shares);
    }

    /// @notice Takes back USTX collateral, as long as what stays still covers the loan;
    ///         `type(uint256).max` takes back all of it.
    function withdrawCollateral(uint256 shares) external returns (uint256 withdrawn) {
        accrueInterest();
        uint256 held = collateralOf[msg.sender];
        withdrawn = shares == type(uint256).max ? held : shares;
        if (withdrawn == 0) revert InvalidAmount();
        if (withdrawn > held) revert InsufficientBalance();
        collateralOf[msg.sender] = held - withdrawn;
        totalCollateral -= withdrawn;
        if (borrowPrincipalOf[msg.sender] != 0) _requireCovered(msg.sender);
        _sendShares(msg.sender, withdrawn);
        emit CollateralWithdrawn(msg.sender, withdrawn);
    }

    /// @notice Borrows `amount` dUSD against the caller's USTX, up to BORROW_COLLATERAL_FACTOR of
    ///         its value at the current NAV. A loan starts at MIN_BORROW.
    function borrow(uint256 amount) external whenNotPaused {
        if (amount == 0) revert InvalidAmount();
        accrueInterest();
        if (amount > cash()) revert InsufficientLiquidity();
        uint256 added = _ceilDiv(amount * WAD, borrowIndex);
        borrowPrincipalOf[msg.sender] += added;
        totalBorrowPrincipal += added;
        if (_debtOf(msg.sender) < MIN_BORROW) revert BelowMinimum();
        _requireCovered(msg.sender);
        _sendDollars(msg.sender, amount);
        emit Borrowed(msg.sender, amount);
    }

    /// @notice Repays up to `amount` dUSD of the caller's loan. Any amount at or above the debt,
    ///         such as `type(uint256).max`, repays exactly the debt.
    function repay(uint256 amount) external returns (uint256 repaid) {
        accrueInterest();
        uint256 principal = borrowPrincipalOf[msg.sender];
        uint256 debt = _ceilDiv(principal * borrowIndex, WAD);
        uint256 burned;
        if (amount >= debt) {
            (repaid, burned) = (debt, principal);
        } else {
            (repaid, burned) = (amount, amount * WAD / borrowIndex);
        }
        if (burned == 0) revert InvalidAmount();
        borrowPrincipalOf[msg.sender] = principal - burned;
        totalBorrowPrincipal -= burned;
        _receiveDollars(msg.sender, repaid);
        emit Repaid(msg.sender, repaid);
    }

    // ---- Liquidators ----

    /// @notice Repays part of `borrower`'s loan once its debt exceeds LIQUIDATION_THRESHOLD of the
    ///         collateral value, and takes USTX worth the repayment plus LIQUIDATION_BONUS at the
    ///         current NAV. Repays at most CLOSE_FACTOR of the debt and at most `maxRepay`, and
    ///         reverts unless at least `minShares` USTX are received.
    function liquidate(address borrower, uint256 maxRepay, uint256 minShares) external returns (uint256 repaid, uint256 seized) {
        if (borrower == msg.sender) revert InvalidAddress();
        accrueInterest();
        (uint256 nav, ) = fund.currentNav();
        uint256 principal = borrowPrincipalOf[borrower];
        uint256 debt = _ceilDiv(principal * borrowIndex, WAD);
        uint256 held = collateralOf[borrower];
        if (debt == 0 || held == 0 || debt <= held * nav * LIQUIDATION_THRESHOLD / (ONE_SHARE * WAD)) revert NotLiquidatable();

        repaid = debt * CLOSE_FACTOR / WAD;
        if (repaid > maxRepay) repaid = maxRepay;
        if (repaid == 0) revert InvalidAmount();
        seized = repaid * (WAD + LIQUIDATION_BONUS) * ONE_SHARE / (WAD * nav);
        if (seized > held) {
            // Too little collateral left for the full bonus: take all of it for proportionally less.
            seized = held;
            repaid = _ceilDiv(held * nav * WAD, ONE_SHARE * (WAD + LIQUIDATION_BONUS));
        }
        if (seized == 0 || seized < minShares) revert SlippageExceeded();
        uint256 burned = repaid >= debt ? principal : repaid * WAD / borrowIndex;
        if (burned == 0) revert InvalidAmount();

        borrowPrincipalOf[borrower] = principal - burned;
        totalBorrowPrincipal -= burned;
        collateralOf[borrower] = held - seized;
        totalCollateral -= seized;
        _receiveDollars(msg.sender, repaid);
        _sendShares(msg.sender, seized);
        emit Liquidated(msg.sender, borrower, repaid, seized, nav);
    }

    // ---- Interest ----

    /// @notice Adds the interest since the last update to every loan and every lender's balance.
    function accrueInterest() public {
        if (block.timestamp == lastAccrualTime) return;
        (supplyIndex, borrowIndex) = _currentIndices();
        lastAccrualTime = block.timestamp;
    }

    // ---- Views ----

    /// @notice dUSD held by the market: what can be withdrawn or borrowed right now.
    function cash() public view returns (uint256) {
        return dollar.balanceOf(address(this));
    }

    function totalSupplied() public view returns (uint256) {
        (uint256 currentSupplyIndex, ) = _currentIndices();
        return totalSupplyPrincipal * currentSupplyIndex / WAD;
    }

    function totalBorrowed() public view returns (uint256) {
        (, uint256 currentBorrowIndex) = _currentIndices();
        return _ceilDiv(totalBorrowPrincipal * currentBorrowIndex, WAD);
    }

    /// @notice The market's share of the interest: dUSD held and lent out beyond what lenders are owed.
    function reserves() external view returns (uint256) {
        uint256 assets = cash() + totalBorrowed();
        uint256 owed = totalSupplied();
        return assets > owed ? assets - owed : 0;
    }

    function supplyBalanceOf(address account) external view returns (uint256) {
        (uint256 currentSupplyIndex, ) = _currentIndices();
        return supplyPrincipalOf[account] * currentSupplyIndex / WAD;
    }

    function borrowBalanceOf(address account) public view returns (uint256) {
        (, uint256 currentBorrowIndex) = _currentIndices();
        return _ceilDiv(borrowPrincipalOf[account] * currentBorrowIndex, WAD);
    }

    function utilization() public view returns (uint256) {
        return _utilization(totalBorrowed(), totalSupplied());
    }

    function borrowRatePerYear() external view returns (uint256) {
        return _borrowRatePerYear(utilization());
    }

    function supplyRatePerYear() external view returns (uint256) {
        uint256 used = utilization();
        return _borrowRatePerYear(used) * used / WAD * (WAD - RESERVE_FACTOR) / WAD;
    }

    /// @notice The collateral's value at the current NAV, how much it lets the account borrow, and
    ///         the debt above which the loan can be liquidated. Reverts without a usable NAV.
    function collateralValueOf(address account) public view returns (uint256 value, uint256 borrowLimit, uint256 liquidationLimit) {
        (uint256 nav, ) = fund.currentNav();
        uint256 shares = collateralOf[account];
        value = shares * nav / ONE_SHARE;
        borrowLimit = shares * nav * BORROW_COLLATERAL_FACTOR / (ONE_SHARE * WAD);
        liquidationLimit = shares * nav * LIQUIDATION_THRESHOLD / (ONE_SHARE * WAD);
    }

    function isLiquidatable(address account) external view returns (bool) {
        uint256 debt = borrowBalanceOf(account);
        if (debt == 0 || collateralOf[account] == 0) return false;
        (, , uint256 liquidationLimit) = collateralValueOf(account);
        return debt > liquidationLimit;
    }

    // ---- Administration ----

    function pause() external onlyAdministrator {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyAdministrator {
        paused = false;
        emit Unpaused(msg.sender);
    }

    function proposeAdministrator(address nextAdministrator) external onlyAdministrator {
        if (nextAdministrator == address(0)) revert InvalidAddress();
        pendingAdministrator = nextAdministrator;
        emit AdministratorProposed(administrator, nextAdministrator);
    }

    function acceptAdministrator() external {
        if (msg.sender != pendingAdministrator) revert Unauthorized();
        address previous = administrator;
        administrator = msg.sender;
        pendingAdministrator = address(0);
        emit AdministratorAccepted(previous, msg.sender);
    }

    // ---- Internals ----

    // The indices as of this block. Interest for the elapsed time is simple at the utilization of
    // the last update, and compounds at every update.
    function _currentIndices() internal view returns (uint256 currentSupplyIndex, uint256 currentBorrowIndex) {
        currentSupplyIndex = supplyIndex;
        currentBorrowIndex = borrowIndex;
        uint256 elapsed = block.timestamp - lastAccrualTime;
        if (elapsed == 0 || totalBorrowPrincipal == 0) return (currentSupplyIndex, currentBorrowIndex);
        uint256 borrowed = _ceilDiv(totalBorrowPrincipal * currentBorrowIndex, WAD);
        uint256 supplied = totalSupplyPrincipal * currentSupplyIndex / WAD;
        uint256 growth = _borrowRatePerYear(_utilization(borrowed, supplied)) * elapsed / SECONDS_PER_YEAR;
        currentBorrowIndex += currentBorrowIndex * growth / WAD;
        // Lenders share the interest pro rata; RESERVE_FACTOR of it stays in the market.
        if (totalSupplyPrincipal != 0) {
            currentSupplyIndex += borrowed * growth * (WAD - RESERVE_FACTOR) / (WAD * totalSupplyPrincipal);
        }
    }

    function _utilization(uint256 borrowed, uint256 supplied) internal pure returns (uint256) {
        if (borrowed == 0) return 0;
        if (borrowed >= supplied) return WAD;
        return borrowed * WAD / supplied;
    }

    function _borrowRatePerYear(uint256 used) internal pure returns (uint256) {
        if (used <= KINK) return BASE_RATE_PER_YEAR + MULTIPLIER_PER_YEAR * used / WAD;
        return BASE_RATE_PER_YEAR + MULTIPLIER_PER_YEAR * KINK / WAD + JUMP_MULTIPLIER_PER_YEAR * (used - KINK) / WAD;
    }

    // Debt with the stored index; call after accrueInterest.
    function _debtOf(address account) internal view returns (uint256) {
        return _ceilDiv(borrowPrincipalOf[account] * borrowIndex, WAD);
    }

    function _requireCovered(address account) internal view {
        (, uint256 borrowLimit, ) = collateralValueOf(account);
        if (_debtOf(account) > borrowLimit) revert InsufficientCollateral();
    }

    function _ceilDiv(uint256 a, uint256 b) internal pure returns (uint256) {
        return a == 0 ? 0 : (a - 1) / b + 1;
    }

    function _receiveDollars(address from, uint256 amount) internal {
        if (!dollar.transferFrom(from, address(this), amount)) revert TransferFailed();
    }

    function _sendDollars(address to, uint256 amount) internal {
        if (!dollar.transfer(to, amount)) revert TransferFailed();
    }

    function _receiveShares(address from, uint256 shares) internal {
        if (!fund.transferFrom(from, address(this), shares)) revert TransferFailed();
    }

    function _sendShares(address to, uint256 shares) internal {
        if (!fund.transfer(to, shares)) revert TransferFailed();
    }
}

contracts/GanymedeNavArbitrage.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface IArbDollar {
    function approve(address spender, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
}

interface IArbFund {
    function dollar() external view returns (address);
    function currentNav() external view returns (uint256 navPerShareMicros, uint64 effectiveAt);
    function approve(address spender, uint256 value) external returns (bool);
    function invest(uint256 dollars, uint256 minShares) external returns (uint256 shares);
    function redeem(uint256 shares, uint256 minDollars) external returns (uint256 dollars);
}

interface IArbPool {
    function fund() external view returns (address);
    function FEE_BPS() external view returns (uint256);
    function getReserves() external view returns (uint256 shares, uint256 dollars);
    function quoteBuy(uint256 dollarsIn) external view returns (uint256 sharesOut);
    function quoteSell(uint256 sharesIn) external view returns (uint256 dollarsOut);
    function buy(uint256 dollarsIn, uint256 minSharesOut, uint256 deadline) external returns (uint256 sharesOut);
    function sell(uint256 sharesIn, uint256 minDollarsOut, uint256 deadline) external returns (uint256 dollarsOut);
}

/// @title GanymedeNavArbitrage
/// @notice Closes the gap between the USTX pool price and the NAV in one transaction, the way ETF
///         creation and redemption keep a fund's market price near its NAV. Below the NAV it buys
///         USTX in the pool and redeems it at the fund; above the NAV it invests at the fund and
///         sells the new USTX in the pool. The caller puts in demo dollars and receives every demo
///         dollar that comes back; the transaction reverts unless that is at least the input plus
///         `minProfit`.
/// @dev Holds nothing between transactions and has no owner.
contract GanymedeNavArbitrage {
    uint256 private constant BPS = 10_000;
    uint256 private constant ONE_SHARE = 1e6;
    // The fund's MIN_INVESTMENT: it refuses smaller investments.
    uint256 private constant MIN_INVESTMENT = 10 * 10 ** 6;

    IArbPool public immutable pool;
    IArbFund public immutable fund;
    IArbDollar public immutable dollar;

    event Arbitraged(address indexed trader, bool boughtInPool, uint256 dollarsIn, uint256 dollarsOut, uint256 navPerShareMicros);

    error InvalidAddress();
    error Unprofitable(uint256 dollarsIn, uint256 dollarsOut);
    error TransferFailed();

    constructor(address ustxPool) {
        if (ustxPool == address(0)) revert InvalidAddress();
        IArbFund basketFund = IArbFund(IArbPool(ustxPool).fund());
        IArbDollar demoDollar = IArbDollar(basketFund.dollar());
        pool = IArbPool(ustxPool);
        fund = basketFund;
        dollar = demoDollar;
        // The fund and the pool pull from this contract only inside a caller's transaction.
        if (!demoDollar.approve(address(basketFund), type(uint256).max)) revert TransferFailed();
        if (!demoDollar.approve(ustxPool, type(uint256).max)) revert TransferFailed();
        if (!basketFund.approve(ustxPool, type(uint256).max)) revert TransferFailed();
    }

    /// @notice Pool below NAV: buys USTX in the pool with `dollarsIn` demo dollars (approved to this
    ///         contract) and redeems it at the fund.
    function buyAndRedeem(uint256 dollarsIn, uint256 minProfit) external returns (uint256 dollarsOut) {
        _receive(dollarsIn);
        uint256 shares = pool.buy(dollarsIn, 0, block.timestamp);
        dollarsOut = fund.redeem(shares, 0);
        _settle(true, dollarsIn, dollarsOut, minProfit);
    }

    /// @notice Pool above NAV: invests `dollarsIn` demo dollars (approved to this contract) at the
    ///         fund and sells the new USTX in the pool.
    function investAndSell(uint256 dollarsIn, uint256 minProfit) external returns (uint256 dollarsOut) {
        _receive(dollarsIn);
        uint256 shares = fund.invest(dollarsIn, 0);
        dollarsOut = pool.sell(shares, 0, block.timestamp);
        _settle(false, dollarsIn, dollarsOut, minProfit);
    }

    /// @notice The trade that captures most of the gap now: whether it buys in the pool (pool below
    ///         NAV) or sells into it (above NAV), the demo dollars to put in and the demo dollars
    ///         expected back. `dollarsIn` is 0 when the gap does not cover the pool fee. Reverts
    ///         without a usable NAV.
    function quote() external view returns (bool buyInPool, uint256 dollarsIn, uint256 dollarsOut) {
        (uint256 nav, ) = fund.currentNav();
        (uint256 s, uint256 d) = pool.getReserves();
        if (s == 0 || d == 0) return (false, 0, 0);
        uint256 keep = BPS - pool.FEE_BPS();
        // Buying x dollars of USTX and redeeming it gains most where (d + γx)² = γ·s·d·NAV, γ = keep/BPS.
        uint256 root = _sqrt(keep * s * d / BPS * nav / ONE_SHARE);
        if (root > d) {
            dollarsIn = (root - d) * BPS / keep;
            if (dollarsIn == 0) return (true, 0, 0);
            dollarsOut = pool.quoteBuy(dollarsIn) * nav / ONE_SHARE;
            return dollarsOut > dollarsIn ? (true, dollarsIn, dollarsOut) : (true, 0, 0);
        }
        // Investing k shares' worth and selling them gains most where (s + γk)² = γ·s·d / NAV.
        root = _sqrt(keep * s * d / BPS * ONE_SHARE / nav);
        if (root <= s) return (false, 0, 0);
        uint256 shares = (root - s) * BPS / keep;
        dollarsIn = shares * nav / ONE_SHARE;
        if (dollarsIn < MIN_INVESTMENT) return (false, 0, 0);
        dollarsOut = pool.quoteSell(dollarsIn * ONE_SHARE / nav);
        return dollarsOut > dollarsIn ? (false, dollarsIn, dollarsOut) : (false, 0, 0);
    }

    function _receive(uint256 amount) internal {
        if (!dollar.transferFrom(msg.sender, address(this), amount)) revert TransferFailed();
    }

    function _settle(bool boughtInPool, uint256 dollarsIn, uint256 dollarsOut, uint256 minProfit) internal {
        if (dollarsOut < dollarsIn + minProfit) revert Unprofitable(dollarsIn, dollarsOut);
        if (!dollar.transfer(msg.sender, dollarsOut)) revert TransferFailed();
        (uint256 nav, ) = fund.currentNav();
        emit Arbitraged(msg.sender, boughtInPool, dollarsIn, dollarsOut, nav);
    }

    function _sqrt(uint256 y) internal pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/GanymedeNavFeed.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

interface INavSource {
    function latestNav(bytes32 productId)
        external
        view
        returns (uint256 navPerShareMicros, uint256 sharesOutstandingMicros, bytes32 holdingsHash, uint64 effectiveAt, uint64 publishedAt);
}

/// @title GanymedeNavFeed
/// @notice One product's NAV from GanymedeNavRegistry, in the AggregatorV3Interface shape that
///         Chainlink price feeds use, so lending markets, vaults and dashboards on X Layer can read
///         it without custom code. It has no owner and no state of its own: every answer is the
///         registry's latest record for the product.
/// @dev Answers have 8 decimals, like Chainlink's USD feeds. The round ID is the record's effective
///      time, which the registry only lets grow, and `startedAt` and `updatedAt` are that same
///      time, so a staleness check on `updatedAt` measures the age of the prices themselves, not of
///      the transaction that published them. Only the latest round is on chain; earlier records
///      are in the registry's NavPublished events.
contract GanymedeNavFeed {
    uint8 public constant decimals = 8;
    uint256 public constant version = 1;
    // Registry NAVs have 6 decimals.
    uint256 private constant MICROS_TO_ANSWER = 100;

    INavSource public immutable registry;
    bytes32 public immutable productId;
    string public description;

    error InvalidAddress();
    error InvalidProduct();
    error NoDataPresent();

    constructor(address navRegistry, bytes32 feedProductId, string memory feedDescription) {
        if (navRegistry == address(0)) revert InvalidAddress();
        if (feedProductId == bytes32(0)) revert InvalidProduct();
        registry = INavSource(navRegistry);
        productId = feedProductId;
        description = feedDescription;
    }

    function latestRoundData()
        public
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (uint256 navPerShareMicros, , , uint64 effectiveAt, ) = registry.latestNav(productId);
        if (navPerShareMicros == 0 || effectiveAt == 0) revert NoDataPresent();
        roundId = uint80(effectiveAt);
        answer = int256(navPerShareMicros * MICROS_TO_ANSWER);
        startedAt = effectiveAt;
        updatedAt = effectiveAt;
        answeredInRound = roundId;
    }

    /// @notice The latest round only; any other round ID reverts with NoDataPresent.
    function getRoundData(uint80 requestedRoundId)
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound)
    {
        (roundId, answer, startedAt, updatedAt, answeredInRound) = latestRoundData();
        if (requestedRoundId != roundId) revert NoDataPresent();
    }

    // The older AggregatorInterface reads, still used by some integrations.
    function latestAnswer() external view returns (int256 answer) {
        (, answer, , , ) = latestRoundData();
    }

    function latestTimestamp() external view returns (uint256 updatedAt) {
        (, , , updatedAt, ) = latestRoundData();
    }

    function latestRound() external view returns (uint256) {
        (uint80 roundId, , , , ) = latestRoundData();
        return roundId;
    }
}

contracts/GanymedeNavRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title GanymedeNavRegistry
/// @notice Append-only publication registry for fund NAV and rebalance evidence.
contract GanymedeNavRegistry {
    struct NavSnapshot {
        uint256 navPerShareMicros;
        uint256 sharesOutstandingMicros;
        bytes32 holdingsHash;
        uint64 effectiveAt;
        uint64 publishedAt;
    }

    address public administrator;
    address public pendingAdministrator;
    address public publisher;
    bool public paused;

    mapping(bytes32 => NavSnapshot) public latestNav;
    mapping(bytes32 => bytes32) public latestRebalanceHash;
    mapping(bytes32 => bool) public publishedPayload;

    event NavPublished(bytes32 indexed productId, uint256 navPerShareMicros, uint256 sharesOutstandingMicros, bytes32 indexed holdingsHash, uint64 effectiveAt);
    event RebalancePublished(bytes32 indexed productId, bytes32 indexed rebalanceHash, uint64 effectiveAt);
    event PublisherChanged(address indexed previousPublisher, address indexed newPublisher);
    event AdministratorProposed(address indexed currentAdministrator, address indexed pendingAdministrator);
    event AdministratorAccepted(address indexed previousAdministrator, address indexed newAdministrator);
    event Paused(address indexed account);
    event Unpaused(address indexed account);

    error Unauthorized();
    error InvalidAddress();
    error InvalidPayload();
    error StalePublication();
    error DuplicatePayload();
    error ContractPaused();

    modifier onlyAdministrator() {
        if (msg.sender != administrator) revert Unauthorized();
        _;
    }

    modifier onlyPublisher() {
        if (msg.sender != publisher) revert Unauthorized();
        _;
    }

    modifier whenNotPaused() {
        if (paused) revert ContractPaused();
        _;
    }

    constructor(address initialAdministrator, address initialPublisher) {
        if (initialAdministrator == address(0) || initialPublisher == address(0)) revert InvalidAddress();
        administrator = initialAdministrator;
        publisher = initialPublisher;
    }

    function publishNav(
        bytes32 productId,
        uint256 navPerShareMicros,
        uint256 sharesOutstandingMicros,
        bytes32 holdingsHash,
        uint64 effectiveAt
    ) external onlyPublisher whenNotPaused {
        if (productId == bytes32(0) || holdingsHash == bytes32(0) || navPerShareMicros == 0) revert InvalidPayload();
        if (effectiveAt <= latestNav[productId].effectiveAt) revert StalePublication();
        bytes32 payloadHash = keccak256(abi.encode(productId, navPerShareMicros, sharesOutstandingMicros, holdingsHash, effectiveAt));
        if (publishedPayload[payloadHash]) revert DuplicatePayload();
        publishedPayload[payloadHash] = true;
        latestNav[productId] = NavSnapshot(navPerShareMicros, sharesOutstandingMicros, holdingsHash, effectiveAt, uint64(block.timestamp));
        emit NavPublished(productId, navPerShareMicros, sharesOutstandingMicros, holdingsHash, effectiveAt);
    }

    function publishRebalance(bytes32 productId, bytes32 rebalanceHash, uint64 effectiveAt) external onlyPublisher whenNotPaused {
        if (productId == bytes32(0) || rebalanceHash == bytes32(0)) revert InvalidPayload();
        bytes32 payloadHash = keccak256(abi.encode(productId, rebalanceHash, effectiveAt));
        if (publishedPayload[payloadHash]) revert DuplicatePayload();
        publishedPayload[payloadHash] = true;
        latestRebalanceHash[productId] = rebalanceHash;
        emit RebalancePublished(productId, rebalanceHash, effectiveAt);
    }

    function setPublisher(address newPublisher) external onlyAdministrator {
        if (newPublisher == address(0)) revert InvalidAddress();
        emit PublisherChanged(publisher, newPublisher);
        publisher = newPublisher;
    }

    function pause() external onlyAdministrator {
        paused = true;
        emit Paused(msg.sender);
    }

    function unpause() external onlyAdministrator {
        paused = false;
        emit Unpaused(msg.sender);
    }

    function proposeAdministrator(address nextAdministrator) external onlyAdministrator {
        if (nextAdministrator == address(0)) revert InvalidAddress();
        pendingAdministrator = nextAdministrator;
        emit AdministratorProposed(administrator, nextAdministrator);
    }

    function acceptAdministrator() external {
        if (msg.sender != pendingAdministrator) revert Unauthorized();
        address previous = administrator;
        administrator = msg.sender;
        pendingAdministrator = address(0);
        emit AdministratorAccepted(previous, msg.sender);
    }
}

