// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId} from "@uniswap/v4-core/src/types/PoolId.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";

interface IRangeHook {
    function poolManager() external view returns (IPoolManager);
    function poolKey() external view returns (PoolKey memory);
    function asset() external view returns (address);
    function dollar() external view returns (address);
    function assetIsCurrency0() external view returns (bool);
    function nav() external view returns (uint256 answer, uint256 updatedAt, uint160 sqrtPriceX96);
    function currentFee() external view returns (uint24);
}

interface IRangeFund {
    function dollar() external view returns (address);
    function approve(address spender, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function currentNav() external view returns (uint256 navPerShareMicros, uint64 effectiveAt);
    function invest(uint256 dollars, uint256 minShares) external returns (uint256 shares);
    function redeem(uint256 shares, uint256 minDollars) external returns (uint256 dollars);
}

interface IRangeDollar {
    function approve(address spender, uint256 value) external returns (bool);
    function transfer(address to, uint256 value) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

/// @title GanymedeRangeArbitrage
/// @notice Brings GanymedeRangeLiquidityHook's pool back to the NAV through the fund, in one
///         transaction and with no money of the caller's: below the NAV it buys USTX in the pool and
///         redeems it at the fund, above it sells USTX into the pool that it invests for at the fund.
///         The swap stops where the pool's price, net of its fee, meets the NAV, so the last unit
///         traded still pays. Every demo dollar left over, and any USTX the fund's $10 minimum
///         investment bought beyond what the pool took, goes to the caller; the transaction reverts
///         unless the demo dollars come to at least `minProfit`. Where no position holds liquidity
///         between the price and the NAV, the swap moves the price across that empty stretch and
///         trades nothing, for a profit of 0: so the pool never stays stuck away from the NAV, where
///         positions cannot open.
/// @dev Holds nothing between transactions and has no owner. The USTX token is the fund itself.
contract GanymedeRangeArbitrage is IUnlockCallback {
    using StateLibrary for IPoolManager;

    uint256 private constant ONE_SHARE = 1e6;
    uint256 private constant MIN_INVESTMENT = 10 * 10 ** 6;
    uint256 private constant PIPS = 1_000_000;

    IRangeHook public immutable hook;
    IPoolManager public immutable poolManager;
    IRangeFund public immutable fund;
    IRangeDollar public immutable dollar;
    bool private immutable assetIsCurrency0;

    event Arbitraged(address indexed trader, bool boughtInPool, uint256 sharesMoved, uint256 profit, uint256 navPerShareMicros);

    error NotPoolManager();
    error InvalidAddress();
    error NothingToDo();
    error Unprofitable(uint256 profit);
    error TransferFailed();

    constructor(address rangeHook, address basketFund) {
        hook = IRangeHook(rangeHook);
        poolManager = IRangeHook(rangeHook).poolManager();
        fund = IRangeFund(basketFund);
        dollar = IRangeDollar(IRangeHook(rangeHook).dollar());
        assetIsCurrency0 = IRangeHook(rangeHook).assetIsCurrency0();
        if (IRangeHook(rangeHook).asset() != basketFund || IRangeFund(basketFund).dollar() != address(dollar)) revert InvalidAddress();
        if (!dollar.approve(basketFund, type(uint256).max)) revert TransferFailed();
    }

    /// @notice Trades the pool to the NAV and keeps the difference. Call it with eth_call first: the
    ///         result is the profit in demo dollars, or a revert when there is nothing to gain.
    function arbitrage(uint256 minProfit) external returns (uint256 profit) {
        (bool buyInPool, uint160 limit) = _direction();
        bytes memory result = poolManager.unlock(abi.encode(buyInPool, limit));
        uint256 moved;
        (profit, moved) = abi.decode(result, (uint256, uint256));
        if (profit < minProfit) revert Unprofitable(profit);
        if (!dollar.transfer(msg.sender, dollar.balanceOf(address(this)))) revert TransferFailed();
        uint256 extra = fund.balanceOf(address(this));
        if (extra > 0 && !fund.transfer(msg.sender, extra)) revert TransferFailed();
        (uint256 navMicros, ) = fund.currentNav();
        emit Arbitraged(msg.sender, buyInPool, moved, profit, navMicros);
    }

    function unlockCallback(bytes calldata data) external returns (bytes memory) {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        (bool buyInPool, uint160 limit) = abi.decode(data, (bool, uint160));
        PoolKey memory key = hook.poolKey();
        // Buying USTX in the pool pays demo dollars for it; selling pays USTX for demo dollars.
        bool zeroForOne = buyInPool ? !assetIsCurrency0 : assetIsCurrency0;
        BalanceDelta delta = poolManager.swap(key, SwapParams(zeroForOne, -int256(uint256(type(uint128).max >> 1)), limit), "");
        (int128 assetDelta, int128 dollarDelta) = assetIsCurrency0 ? (delta.amount0(), delta.amount1()) : (delta.amount1(), delta.amount0());
        Currency assetCurrency = Currency.wrap(address(fund));
        Currency dollarCurrency = Currency.wrap(address(dollar));
        if (buyInPool) {
            uint256 shares = uint256(uint128(assetDelta));
            uint256 owed = uint256(uint128(-dollarDelta));
            // Nothing between the price and the NAV: the price moved across an empty stretch.
            if (shares == 0 && owed == 0) return abi.encode(uint256(0), uint256(0));
            if (shares == 0) revert NothingToDo();
            poolManager.take(assetCurrency, address(this), shares);
            uint256 dollars = fund.redeem(shares, 0);
            if (dollars < owed) revert Unprofitable(0);
            _pay(dollarCurrency, owed);
            return abi.encode(dollars - owed, shares);
        }
        uint256 owedShares = uint256(uint128(-assetDelta));
        uint256 received = uint256(uint128(dollarDelta));
        if (owedShares == 0 && received == 0) return abi.encode(uint256(0), uint256(0));
        if (owedShares == 0) revert NothingToDo();
        poolManager.take(dollarCurrency, address(this), received);
        (uint256 navMicros, ) = fund.currentNav();
        // Enough demo dollars for the shares owed at the fund's rounding, and at least its minimum.
        uint256 invest = (owedShares * navMicros + ONE_SHARE - 1) / ONE_SHARE + 1;
        if (invest < MIN_INVESTMENT) invest = MIN_INVESTMENT;
        if (invest > received) revert Unprofitable(0);
        fund.invest(invest, owedShares);
        _payShares(assetCurrency, owedShares);
        return abi.encode(received - invest, owedShares);
    }

    /// @dev Which way the pool is off the NAV, and the price the swap stops at: where the last unit
    ///      breaks even after the fee, NAV·(1 − fee) buying in the pool and NAV / (1 − fee) selling
    ///      into it. Reverts when the pool is within its fee of the NAV.
    function _direction() private view returns (bool buyInPool, uint160 limit) {
        (, , uint160 navSqrt) = hook.nav();
        uint24 fee = hook.currentFee();
        (uint160 poolSqrt, , , ) = poolManager.getSlot0(hook.poolKey().toId());
        // Pool prices are currency1 per currency0; USTX is cheap in the pool when its price in demo
        // dollars is below the NAV.
        bool assetCheap = assetIsCurrency0 ? poolSqrt < navSqrt : poolSqrt > navSqrt;
        uint256 lowSqrt = uint256(navSqrt) * _sqrt((PIPS - fee) * PIPS) / PIPS;
        uint256 highSqrt = uint256(navSqrt) * _sqrt(PIPS * PIPS * PIPS / (PIPS - fee)) / PIPS;
        // In currency1-per-currency0 terms, buying the asset (currency0) raises the price toward the
        // NAV less the fee; when the asset is currency1 the directions swap.
        if (assetIsCurrency0) {
            limit = uint160(assetCheap ? lowSqrt : highSqrt);
            if (assetCheap ? poolSqrt >= limit : poolSqrt <= limit) revert NothingToDo();
        } else {
            limit = uint160(assetCheap ? highSqrt : lowSqrt);
            if (assetCheap ? poolSqrt <= limit : poolSqrt >= limit) revert NothingToDo();
        }
        if (limit <= TickMath.MIN_SQRT_PRICE || limit >= TickMath.MAX_SQRT_PRICE) revert NothingToDo();
        buyInPool = assetCheap;
    }

    function _pay(Currency currency, uint256 amount) private {
        poolManager.sync(currency);
        if (!dollar.transfer(address(poolManager), amount)) revert TransferFailed();
        poolManager.settle();
    }

    function _payShares(Currency currency, uint256 amount) private {
        poolManager.sync(currency);
        if (!fund.transfer(address(poolManager), amount)) revert TransferFailed();
        poolManager.settle();
    }

    function _sqrt(uint256 y) private pure returns (uint256 z) {
        if (y > 3) {
            z = y;
            uint256 x = y / 2 + 1;
            while (x < z) {
                z = x;
                x = (y / x + x) / 2;
            }
        } else if (y != 0) {
            z = 1;
        }
    }
}

contracts/GanymedeRangeLiquidityHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {LPFeeLibrary} from "@uniswap/v4-core/src/libraries/LPFeeLibrary.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {SqrtPriceMath} from "@uniswap/v4-core/src/libraries/SqrtPriceMath.sol";
import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {FixedPoint96} from "@uniswap/v4-core/src/libraries/FixedPoint96.sol";
import {FixedPoint128} from "@uniswap/v4-core/src/libraries/FixedPoint128.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId} from "@uniswap/v4-core/src/types/PoolId.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {BeforeSwapDelta, BeforeSwapDeltaLibrary} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {ModifyLiquidityParams, SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";

interface IRangeNavFeed {
    function decimals() external view returns (uint8);
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

interface IRangePoolToken {
    function decimals() external view returns (uint8);
}

/// @title GanymedeRangeLiquidityHook
/// @notice A Uniswap v4 pool for a real-world-asset token against a dollar token in which every
///         liquidity provider holds positions of their own, shaped as Meteora shapes them: a run of
///         equal-width bins either side of the pool's price, the dollar token in the bins below it
///         and the asset in the bins above, spread evenly (Spot), heaviest next to the price (Curve)
///         or heaviest at the far ends (Bid-Ask). On X Layer Testnet: USTX against dUSD, priced by
///         GanymedeNavFeed.
///
///         The NAV guards the pool rather than moving it. Positions open only while the pool's price
///         is within OPEN_TICKS of the NAV, so a moved price cannot place someone's bins; swaps need
///         a NAV at most MAX_NAV_AGE old and pay a fee that rises from MIN_FEE at a fresh NAV to
///         MAX_FEE at that age; and no swap may leave the price more than BAND_TICKS from the NAV.
///         Arbitrage through the fund (GanymedeRangeArbitrage) brings the price back to the NAV.
/// @dev Pool: the two tokens sorted by address, a dynamic fee and TICK_SPACING, with this hook, opened
///      at the NAV in the constructor. The pool manager does not call a hook back for its own calls;
///      the hook refuses every other pool and all liquidity it does not add itself. Each position's
///      liquidity sits in the pool manager under this hook with the position's id as its salt, so
///      positions never share fees. Closing pays the position's tokens and fees to its owner at any
///      NAV, stale or missing. No owner, no pause, nothing to configure.
contract GanymedeRangeLiquidityHook is IHooks, IUnlockCallback {
    using StateLibrary for IPoolManager;

    enum Shape {
        Spot,
        Curve,
        BidAsk
    }

    struct Position {
        address owner;
        Shape shape;
        /// @notice The lower tick of the tick-spacing interval the price was in at opening; bins
        ///         below end at it, bins above start one spacing over it.
        int24 center;
        int24 binTicks;
        uint8 binsBelow;
        uint8 binsAbove;
        bool open;
    }

    enum Action {
        Open,
        Close
    }

    int24 public constant TICK_SPACING = 10;
    /// @notice Bins are 10 to 500 ticks wide (0.1% to about 5%), in whole tick spacings.
    int24 public constant MAX_BIN_TICKS = 500;
    /// @notice At most this many bins on each side.
    uint8 public constant MAX_BINS = 20;
    /// @notice Positions open only with the price at most this many ticks from the NAV (≈ 1%).
    int24 public constant OPEN_TICKS = 100;
    /// @notice No swap may leave the price more than this many ticks from the NAV (≈ 5%).
    int24 public constant BAND_TICKS = 500;
    uint24 public constant MIN_FEE = 3_000;
    uint24 public constant MAX_FEE = 10_000;
    uint256 public constant MAX_NAV_AGE = 1 hours;
    uint256 public constant CLOCK_TOLERANCE = 60;

    IPoolManager public immutable poolManager;
    IRangeNavFeed public immutable navFeed;
    address public immutable asset;
    address public immutable dollar;
    Currency public immutable currency0;
    Currency public immutable currency1;
    bool public immutable assetIsCurrency0;
    PoolId public immutable poolId;
    uint256 private immutable navUnit;
    uint256 private immutable dollarUnit;

    uint256 public nextPositionId = 1;
    mapping(uint256 => Position) public positions;
    mapping(uint256 => uint128[]) private _liquidity;
    mapping(address => uint256[]) private _positionsOf;
    uint256 private _locked = 1;

    event PositionOpened(
        uint256 indexed id,
        address indexed owner,
        Shape shape,
        int24 center,
        int24 binTicks,
        uint8 binsBelow,
        uint8 binsAbove,
        uint256 amount0,
        uint256 amount1
    );
    event PositionClosed(uint256 indexed id, address indexed owner, uint256 amount0, uint256 amount1);

    error NotPoolManager();
    error HookNotImplemented();
    error PoolOpenedByHook();
    error LiquidityThroughHook();
    error InvalidAddress();
    error InvalidToken();
    error InvalidShape();
    error InvalidAmount();
    error NotOwner();
    error PositionClosedAlready();
    error Expired();
    error SlippageExceeded();
    error PriceAwayFromNav(int24 tick, int24 navTick);
    error NavUnavailable();
    error NavTooOld(uint256 updatedAt);
    error NavInFuture(uint256 updatedAt);
    error NavOutOfRange();
    error OutsideBand(int24 tick, int24 navTick);
    error TransferFailed();
    error Reentrancy();

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    modifier beforeDeadline(uint256 deadline) {
        if (block.timestamp > deadline) revert Expired();
        _;
    }

    /// @dev Deploy at an address whose low bits carry exactly these permissions (a CREATE2 salt).
    constructor(address manager, address assetToken, address dollarToken, address feed) {
        if (manager == address(0) || feed == address(0)) revert InvalidAddress();
        if (assetToken == address(0) || dollarToken == address(0) || assetToken == dollarToken) revert InvalidAddress();
        Hooks.validateHookPermissions(
            IHooks(address(this)),
            Hooks.Permissions({
                beforeInitialize: true,
                afterInitialize: false,
                beforeAddLiquidity: true,
                afterAddLiquidity: false,
                beforeRemoveLiquidity: false,
                afterRemoveLiquidity: false,
                beforeSwap: true,
                afterSwap: true,
                beforeDonate: false,
                afterDonate: false,
                beforeSwapReturnDelta: false,
                afterSwapReturnDelta: false,
                afterAddLiquidityReturnDelta: false,
                afterRemoveLiquidityReturnDelta: false
            })
        );
        uint256 dollarDecimals = IRangePoolToken(dollarToken).decimals();
        uint256 priceDecimals = uint256(IRangeNavFeed(feed).decimals()) + IRangePoolToken(assetToken).decimals();
        if (dollarDecimals < 6 || dollarDecimals > 18 || priceDecimals > 36) revert InvalidToken();

        poolManager = IPoolManager(manager);
        navFeed = IRangeNavFeed(feed);
        asset = assetToken;
        dollar = dollarToken;
        bool assetFirst = assetToken < dollarToken;
        assetIsCurrency0 = assetFirst;
        currency0 = Currency.wrap(assetFirst ? assetToken : dollarToken);
        currency1 = Currency.wrap(assetFirst ? dollarToken : assetToken);
        dollarUnit = 10 ** dollarDecimals;
        navUnit = 10 ** priceDecimals;

        PoolKey memory key = poolKey();
        poolId = key.toId();
        (uint160 sqrtPriceX96, , ) = _nav();
        poolManager.initialize(key, sqrtPriceX96);
    }

    // ---- Liquidity providers ----

    /// @notice Opens a position for the caller: `binsBelow` bins of `binTicks` ticks below the
    ///         price, funded with up to `amount1` of currency1, and `binsAbove` above it, funded with
    ///         up to `amount0` of currency0 (both approved to this contract), each side spread by
    ///         `shape`. The interval the price is in is left out, so every bin holds one token. Needs
    ///         a NAV at most MAX_NAV_AGE old and the price within OPEN_TICKS of it. Takes only what
    ///         the bins use, which is at most the amounts given; PositionOpened records it.
    function open(Shape shape, int24 binTicks, uint8 binsBelow, uint8 binsAbove, uint256 amount0, uint256 amount1, uint256 deadline)
        external
        nonReentrant
        beforeDeadline(deadline)
        returns (uint256 id)
    {
        _checkShape(binTicks, binsBelow, binsAbove, amount0, amount1);
        Position memory position = Position(msg.sender, shape, 0, binTicks, binsBelow, binsAbove, true);
        id = abi.decode(poolManager.unlock(abi.encode(Action.Open, abi.encode(position, amount0, amount1))), (uint256));
    }

    function _checkShape(int24 binTicks, uint8 binsBelow, uint8 binsAbove, uint256 amount0, uint256 amount1) private pure {
        if (binTicks < TICK_SPACING || binTicks > MAX_BIN_TICKS || binTicks % TICK_SPACING != 0) revert InvalidShape();
        if (binsBelow > MAX_BINS || binsAbove > MAX_BINS || (binsBelow == 0 && binsAbove == 0)) revert InvalidShape();
        if ((binsBelow > 0) != (amount1 > 0) || (binsAbove > 0) != (amount0 > 0)) revert InvalidAmount();
    }

    /// @notice Closes the caller's position `id`: removes every bin's liquidity and pays its tokens and
    ///         fees to the caller, at any NAV.
    function close(uint256 id, uint256 amount0Min, uint256 amount1Min, uint256 deadline)
        external
        nonReentrant
        beforeDeadline(deadline)
        returns (uint256 amount0, uint256 amount1)
    {
        Position memory position = positions[id];
        if (position.owner != msg.sender) revert NotOwner();
        if (!position.open) revert PositionClosedAlready();
        (amount0, amount1) = abi.decode(poolManager.unlock(abi.encode(Action.Close, abi.encode(id))), (uint256, uint256));
        if (amount0 < amount0Min || amount1 < amount1Min) revert SlippageExceeded();
    }

    function unlockCallback(bytes calldata data) external onlyPoolManager returns (bytes memory) {
        (Action action, bytes memory body) = abi.decode(data, (Action, bytes));
        if (action == Action.Open) return _open(body);
        uint256 id = abi.decode(body, (uint256));
        (uint256 amount0, uint256 amount1) = _close(id);
        return abi.encode(amount0, amount1);
    }

    // ---- Hook callbacks ----

    function beforeInitialize(address, PoolKey calldata, uint160) external pure returns (bytes4) {
        revert PoolOpenedByHook();
    }

    /// @dev Only the hook adds liquidity, and the pool manager does not call it back for its own calls.
    function beforeAddLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert LiquidityThroughHook();
    }

    /// @dev Needs a NAV at most MAX_NAV_AGE old and sets the fee for its age.
    function beforeSwap(address, PoolKey calldata, SwapParams calldata, bytes calldata)
        external
        view
        onlyPoolManager
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        (, uint256 updatedAt, ) = _nav();
        return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, _fee(updatedAt) | LPFeeLibrary.OVERRIDE_FEE_FLAG);
    }

    /// @dev No swap may leave the price more than BAND_TICKS from the NAV.
    function afterSwap(address, PoolKey calldata, SwapParams calldata, BalanceDelta, bytes calldata)
        external
        view
        onlyPoolManager
        returns (bytes4, int128)
    {
        (, int24 tick, , ) = poolManager.getSlot0(poolId);
        (uint160 navSqrt, , ) = _nav();
        int24 navTick = TickMath.getTickAtSqrtPrice(navSqrt);
        if (tick > navTick + BAND_TICKS || tick < navTick - BAND_TICKS) revert OutsideBand(tick, navTick);
        return (IHooks.afterSwap.selector, 0);
    }

    function afterInitialize(address, PoolKey calldata, uint160, int24) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterAddLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata)
        external
        pure
        returns (bytes4, BalanceDelta)
    {
        revert HookNotImplemented();
    }

    function beforeRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert HookNotImplemented();
    }

    function afterRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata)
        external
        pure
        returns (bytes4, BalanceDelta)
    {
        revert HookNotImplemented();
    }

    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    // ---- Views ----

    function poolKey() public view returns (PoolKey memory) {
        return PoolKey({
            currency0: currency0,
            currency1: currency1,
            fee: LPFeeLibrary.DYNAMIC_FEE_FLAG,
            tickSpacing: TICK_SPACING,
            hooks: IHooks(address(this))
        });
    }

    /// @notice The NAV swaps use now and the pool price it maps to. Reverts when the NAV is missing
    ///         or older than MAX_NAV_AGE.
    function nav() external view returns (uint256 answer, uint256 updatedAt, uint160 sqrtPriceX96) {
        (sqrtPriceX96, updatedAt, answer) = _nav();
    }

    /// @notice The fee a swap pays now, in hundredths of a basis point. Reverts like `nav()`.
    function currentFee() external view returns (uint24) {
        (, uint256 updatedAt, ) = _nav();
        return _fee(updatedAt);
    }

    /// @notice Every position `account` has opened, open or closed, oldest first.
    function positionsOf(address account) external view returns (uint256[] memory) {
        return _positionsOf[account];
    }

    /// @notice A position's bins, lowest first: each one's lower and upper tick and liquidity.
    function binsOf(uint256 id) external view returns (int24[] memory lowers, int24[] memory uppers, uint128[] memory liquidity) {
        Position memory position = positions[id];
        uint256 count = uint256(position.binsBelow) + position.binsAbove;
        lowers = new int24[](count);
        uppers = new int24[](count);
        liquidity = _liquidity[id];
        for (uint256 index = 0; index < count; index++) (lowers[index], uppers[index]) = _bin(position, index);
    }

    /// @notice What closing `id` would pay now: its tokens at the pool's price and their uncollected
    ///         fees, rounded down. Zero once closed.
    function positionAmounts(uint256 id) external view returns (uint256 amount0, uint256 amount1, uint256 fees0, uint256 fees1) {
        Position memory position = positions[id];
        if (!position.open) return (0, 0, 0, 0);
        uint128[] memory liquidity = _liquidity[id];
        for (uint256 index = 0; index < liquidity.length; index++) {
            (uint256 a0, uint256 a1, uint256 f0, uint256 f1) = _binAmounts(position, index, liquidity[index], bytes32(id));
            amount0 += a0 + f0;
            amount1 += a1 + f1;
            fees0 += f0;
            fees1 += f1;
        }
    }

    /// @dev One bin's tokens at the pool's price and its uncollected fees.
    function _binAmounts(Position memory position, uint256 index, uint128 liquidity, bytes32 salt)
        private
        view
        returns (uint256 amount0, uint256 amount1, uint256 fees0, uint256 fees1)
    {
        (uint160 sqrtPriceX96, int24 tick, , ) = poolManager.getSlot0(poolId);
        (int24 lower, int24 upper) = _bin(position, index);
        (amount0, amount1) = _amountsFor(lower, upper, liquidity, sqrtPriceX96, tick);
        (fees0, fees1) = _pendingFees(lower, upper, liquidity, salt);
    }

    // ---- Inside the pool manager's unlock ----

    function _open(bytes memory body) private returns (bytes memory) {
        (Position memory position, uint256 amount0, uint256 amount1) = abi.decode(body, (Position, uint256, uint256));
        position.center = _openingCenter(position);
        uint256 id = nextPositionId++;
        positions[id] = position;
        _positionsOf[position.owner].push(id);
        (uint256 owed0, uint256 owed1) = _addBins(id, position, amount0, amount1);
        if (owed0 == 0 && owed1 == 0) revert InvalidAmount();
        _receive(currency0, position.owner, owed0);
        _receive(currency1, position.owner, owed1);
        emit PositionOpened(id, position.owner, position.shape, position.center, position.binTicks, position.binsBelow, position.binsAbove, owed0, owed1);
        return abi.encode(id);
    }

    /// @dev The interval the price is in, which must be within OPEN_TICKS of a fresh NAV, with room
    ///      for the bins on both sides.
    function _openingCenter(Position memory position) private view returns (int24 center) {
        (uint160 navSqrt, , ) = _nav();
        (, int24 tick, , ) = poolManager.getSlot0(poolId);
        int24 navTick = TickMath.getTickAtSqrtPrice(navSqrt);
        if (tick > navTick + OPEN_TICKS || tick < navTick - OPEN_TICKS) revert PriceAwayFromNav(tick, navTick);
        center = _floor(tick);
        if (
            center - int24(uint24(position.binsBelow)) * position.binTicks < TickMath.MIN_TICK
                || center + TICK_SPACING + int24(uint24(position.binsAbove)) * position.binTicks > TickMath.MAX_TICK
        ) revert InvalidShape();
    }

    /// @dev Adds every bin of a new position, each side spread by its shape, and returns what it owes.
    function _addBins(uint256 id, Position memory position, uint256 amount0, uint256 amount1) private returns (uint256 owed0, uint256 owed1) {
        uint256 total = uint256(position.binsBelow) + position.binsAbove;
        for (uint256 index = 0; index < total; index++) {
            (uint256 bin0, uint256 bin1) = _addBin(id, position, index, amount0, amount1);
            owed0 += bin0;
            owed1 += bin1;
        }
    }

    function _addBin(uint256 id, Position memory position, uint256 index, uint256 amount0, uint256 amount1) private returns (uint256 owed0, uint256 owed1) {
        (int24 lower, int24 upper) = _bin(position, index);
        uint128 amount = _binLiquidity(position, index, lower, upper, index < position.binsBelow ? amount1 : amount0);
        _liquidity[id].push(amount);
        if (amount == 0) return (0, 0);
        (BalanceDelta delta, ) = poolManager.modifyLiquidity(poolKey(), ModifyLiquidityParams(lower, upper, int256(uint256(amount)), bytes32(id)), "");
        return (uint256(uint128(-delta.amount0())), uint256(uint128(-delta.amount1())));
    }

    /// @dev A bin's liquidity for its side's `amount`: its share by the shape's weight, currency1
    ///      below the price and currency0 above it. Distance 1 is the bin next to the price.
    function _binLiquidity(Position memory position, uint256 index, int24 lower, int24 upper, uint256 amount) private pure returns (uint128) {
        bool below = index < position.binsBelow;
        uint256 count = below ? position.binsBelow : position.binsAbove;
        uint256 distance = below ? position.binsBelow - index : index - position.binsBelow + 1;
        uint256 part = FullMath.mulDiv(amount, _weight(position.shape, distance, count), _weights(position.shape, count));
        uint160 sqrtLower = TickMath.getSqrtPriceAtTick(lower);
        uint160 sqrtUpper = TickMath.getSqrtPriceAtTick(upper);
        return below ? _liquidityForAmount1(sqrtLower, sqrtUpper, part) : _liquidityForAmount0(sqrtLower, sqrtUpper, part);
    }

    function _close(uint256 id) private returns (uint256 amount0, uint256 amount1) {
        Position memory position = positions[id];
        positions[id].open = false;
        uint128[] memory liquidity = _liquidity[id];
        PoolKey memory key = poolKey();
        for (uint256 index = 0; index < liquidity.length; index++) {
            if (liquidity[index] == 0) continue;
            (int24 lower, int24 upper) = _bin(position, index);
            (BalanceDelta delta, ) =
                poolManager.modifyLiquidity(key, ModifyLiquidityParams(lower, upper, -int256(uint256(liquidity[index])), bytes32(id)), "");
            amount0 += uint256(uint128(delta.amount0()));
            amount1 += uint256(uint128(delta.amount1()));
        }
        if (amount0 > 0) poolManager.take(currency0, position.owner, amount0);
        if (amount1 > 0) poolManager.take(currency1, position.owner, amount1);
        emit PositionClosed(id, position.owner, amount0, amount1);
    }

    /// @dev Bin `index` of a position, lowest first: the bins below end at `center`; the bins above
    ///      start one tick spacing over it, past the interval the price was in.
    function _bin(Position memory position, uint256 index) private pure returns (int24 lower, int24 upper) {
        if (index < position.binsBelow) {
            int24 steps = int24(uint24(position.binsBelow - index));
            lower = position.center - steps * position.binTicks;
            upper = lower + position.binTicks;
        } else {
            int24 steps = int24(uint24(index - position.binsBelow));
            lower = position.center + TICK_SPACING + steps * position.binTicks;
            upper = lower + position.binTicks;
        }
    }

    /// @dev A bin's weight by its distance from the price, 1 for the nearest, out of `count`.
    function _weight(Shape shape, uint256 distance, uint256 count) private pure returns (uint256) {
        if (shape == Shape.Spot) return 1;
        if (shape == Shape.Curve) return count + 1 - distance;
        return distance;
    }

    function _weights(Shape shape, uint256 count) private pure returns (uint256) {
        return shape == Shape.Spot ? count : count * (count + 1) / 2;
    }

    function _floor(int24 tick) private pure returns (int24) {
        int24 floored = (tick / TICK_SPACING) * TICK_SPACING;
        return tick < 0 && tick % TICK_SPACING != 0 ? floored - TICK_SPACING : floored;
    }

    /// @dev Pays the pool manager `amount` of `currency` from `payer`, which approved this contract.
    function _receive(Currency currency, address payer, uint256 amount) private {
        if (amount == 0) return;
        poolManager.sync(currency);
        (bool ok, bytes memory result) =
            Currency.unwrap(currency).call(abi.encodeWithSelector(0x23b872dd, payer, address(poolManager), amount)); // transferFrom
        if (!ok || (result.length != 0 && !abi.decode(result, (bool)))) revert TransferFailed();
        poolManager.settle();
    }

    // ---- Pricing ----

    function _nav() private view returns (uint160 sqrtPriceX96, uint256 updatedAt, uint256 answer) {
        (, int256 reported, , uint256 updated, ) = navFeed.latestRoundData();
        if (reported <= 0 || updated == 0) revert NavUnavailable();
        if (updated > block.timestamp + CLOCK_TOLERANCE) revert NavInFuture(updated);
        if (block.timestamp > updated + MAX_NAV_AGE) revert NavTooOld(updated);
        if (uint256(reported) > type(uint128).max) revert NavOutOfRange();
        answer = uint256(reported);
        updatedAt = updated;
        uint256 dollarsPerAsset = answer * dollarUnit;
        (uint256 numerator, uint256 denominator) = assetIsCurrency0 ? (dollarsPerAsset, navUnit) : (navUnit, dollarsPerAsset);
        if (numerator / denominator >= 1 << 64) revert NavOutOfRange();
        uint256 root = _sqrt(FullMath.mulDiv(numerator, 1 << 192, denominator));
        if (root <= TickMath.MIN_SQRT_PRICE) revert NavOutOfRange();
        sqrtPriceX96 = uint160(root);
    }

    function _fee(uint256 updatedAt) private view returns (uint24) {
        uint256 age = block.timestamp > updatedAt ? block.timestamp - updatedAt : 0;
        return uint24(MIN_FEE + (uint256(MAX_FEE - MIN_FEE) * age) / MAX_NAV_AGE);
    }

    function _amountsFor(int24 lower, int24 upper, uint128 liquidity, uint160 sqrtPriceX96, int24 tick)
        private
        pure
        returns (uint256 amount0, uint256 amount1)
    {
        if (liquidity == 0) return (0, 0);
        uint160 sqrtLower = TickMath.getSqrtPriceAtTick(lower);
        uint160 sqrtUpper = TickMath.getSqrtPriceAtTick(upper);
        if (tick < lower) {
            amount0 = SqrtPriceMath.getAmount0Delta(sqrtLower, sqrtUpper, liquidity, false);
        } else if (tick < upper) {
            amount0 = SqrtPriceMath.getAmount0Delta(sqrtPriceX96, sqrtUpper, liquidity, false);
            amount1 = SqrtPriceMath.getAmount1Delta(sqrtLower, sqrtPriceX96, liquidity, false);
        } else {
            amount1 = SqrtPriceMath.getAmount1Delta(sqrtLower, sqrtUpper, liquidity, false);
        }
    }

    function _pendingFees(int24 lower, int24 upper, uint128 liquidity, bytes32 salt) private view returns (uint256 fees0, uint256 fees1) {
        if (liquidity == 0) return (0, 0);
        (uint256 inside0, uint256 inside1) = poolManager.getFeeGrowthInside(poolId, lower, upper);
        bytes32 positionKey = keccak256(abi.encodePacked(address(this), lower, upper, salt));
        (, uint256 last0, uint256 last1) = poolManager.getPositionInfo(poolId, positionKey);
        unchecked {
            fees0 = FullMath.mulDiv(inside0 - last0, liquidity, FixedPoint128.Q128);
            fees1 = FullMath.mulDiv(inside1 - last1, liquidity, FixedPoint128.Q128);
        }
    }

    // Uniswap's LiquidityAmounts for one token, rounded down: adding the result never needs more
    // than the amount given.
    function _liquidityForAmount0(uint160 sqrtLower, uint160 sqrtUpper, uint256 amount0) private pure returns (uint128) {
        uint256 intermediate = FullMath.mulDiv(sqrtLower, sqrtUpper, FixedPoint96.Q96);
        return _toUint128(FullMath.mulDiv(amount0, intermediate, sqrtUpper - sqrtLower));
    }

    function _liquidityForAmount1(uint160 sqrtLower, uint160 sqrtUpper, uint256 amount1) private pure returns (uint128) {
        return _toUint128(FullMath.mulDiv(amount1, FixedPoint96.Q96, sqrtUpper - sqrtLower));
    }

    function _toUint128(uint256 value) private pure returns (uint128) {
        if (value > type(uint128).max) revert InvalidAmount();
        return uint128(value);
    }

    /// @dev Floor of the square root, as OpenZeppelin's Math.sqrt.
    function _sqrt(uint256 x) private pure returns (uint256) {
        if (x == 0) return 0;
        uint256 xx = x;
        uint256 r = 1;
        if (xx >= 0x100000000000000000000000000000000) {
            xx >>= 128;
            r <<= 64;
        }
        if (xx >= 0x10000000000000000) {
            xx >>= 64;
            r <<= 32;
        }
        if (xx >= 0x100000000) {
            xx >>= 32;
            r <<= 16;
        }
        if (xx >= 0x10000) {
            xx >>= 16;
            r <<= 8;
        }
        if (xx >= 0x100) {
            xx >>= 8;
            r <<= 4;
        }
        if (xx >= 0x10) {
            xx >>= 4;
            r <<= 2;
        }
        if (xx >= 0x8) r <<= 1;
        for (uint256 i = 0; i < 7; i++) r = (r + x / r) >> 1;
        uint256 r1 = x / r;
        return r < r1 ? r : r1;
    }
}

contracts/GanymedeRwaLiquidityHook.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {IHooks} from "@uniswap/v4-core/src/interfaces/IHooks.sol";
import {IPoolManager} from "@uniswap/v4-core/src/interfaces/IPoolManager.sol";
import {IUnlockCallback} from "@uniswap/v4-core/src/interfaces/callback/IUnlockCallback.sol";
import {Hooks} from "@uniswap/v4-core/src/libraries/Hooks.sol";
import {LPFeeLibrary} from "@uniswap/v4-core/src/libraries/LPFeeLibrary.sol";
import {StateLibrary} from "@uniswap/v4-core/src/libraries/StateLibrary.sol";
import {TickMath} from "@uniswap/v4-core/src/libraries/TickMath.sol";
import {SqrtPriceMath} from "@uniswap/v4-core/src/libraries/SqrtPriceMath.sol";
import {FullMath} from "@uniswap/v4-core/src/libraries/FullMath.sol";
import {FixedPoint96} from "@uniswap/v4-core/src/libraries/FixedPoint96.sol";
import {FixedPoint128} from "@uniswap/v4-core/src/libraries/FixedPoint128.sol";
import {Currency} from "@uniswap/v4-core/src/types/Currency.sol";
import {PoolKey} from "@uniswap/v4-core/src/types/PoolKey.sol";
import {PoolId} from "@uniswap/v4-core/src/types/PoolId.sol";
import {BalanceDelta} from "@uniswap/v4-core/src/types/BalanceDelta.sol";
import {BeforeSwapDelta, BeforeSwapDeltaLibrary} from "@uniswap/v4-core/src/types/BeforeSwapDelta.sol";
import {ModifyLiquidityParams, SwapParams} from "@uniswap/v4-core/src/types/PoolOperation.sol";

interface IRwaNavFeed {
    function decimals() external view returns (uint8);
    function latestRoundData()
        external
        view
        returns (uint80 roundId, int256 answer, uint256 startedAt, uint256 updatedAt, uint80 answeredInRound);
}

interface IRwaPoolToken {
    function decimals() external view returns (uint8);
}

/// @title GanymedeRwaLiquidityHook
/// @notice A Uniswap v4 pool for a real-world-asset token against a dollar token, run around the
///         asset's NAV, and the vault of the liquidity providers who fund it: on X Layer Testnet,
///         USTX against dUSD, priced by GanymedeNavFeed. The hook owns all of the pool's liquidity
///         and issues ERC-20 shares for it. Liquidity providers deposit both tokens at the ratio the
///         hook holds them and withdraw their share of everything it holds, fees included. Deposits
///         are priced forward, like a fund's subscriptions: each one waits for the first NAV record
///         published after it and becomes shares there, valued with the holdings at that NAV, so it
///         earns nothing from trades made before its liquidity is in the pool.
///
///         At every new NAV record the hook takes its liquidity out, moves the empty pool to the NAV
///         and puts the liquidity back around it: a base range BASE_TICKS either side of the NAV, as
///         large as the holdings allow, and whatever the base range cannot use as a one-sided range
///         LIMIT_TICKS wide next to the NAV, on the side where that token sells. Moving an empty pool
///         exchanges nothing, so the pool's price follows the NAV without arbitrageurs trading
///         against the liquidity providers at the old price. Between records the pool trades on
///         Uniswap's concentrated-liquidity curve with a fee that rises from MIN_FEE at a fresh NAV
///         to MAX_FEE at MAX_NAV_AGE; past that age swaps stop until a new record arrives, and no
///         swap may leave the price more than BAND_TICKS from the NAV.
/// @dev Pool: the two tokens sorted by address, a dynamic fee and TICK_SPACING, with this hook. It is
///      opened at the NAV in the constructor; the pool manager does not call a hook back for its
///      own calls, and the hook refuses every other pool and all liquidity it does not add itself.
///      The first deposit mints its value at the NAV in dollar units and locks MINIMUM_SHARES.
///      Later deposits take each token in proportion to the holdings, wait as ERC-6909 claims in the
///      pool manager, and at the next re-peg mint shares for their value against the holdings' value
///      at that NAV, rounded down; each depositor then claims their part, and can cancel before.
///      Withdrawals receive the shares' part of everything held, rounded down. Tokens sent to the
///      hook outside a deposit are ignored. Standard ERC-20 tokens only: a token that delivers less
///      than it is asked to send leaves the pool manager unsettled and the call reverts. No owner,
///      no pause, nothing to configure.
contract GanymedeRwaLiquidityHook is IHooks, IUnlockCallback {
    using StateLibrary for IPoolManager;

    struct Range {
        int24 lower;
        int24 upper;
        uint128 liquidity;
    }

    /// @notice A deposit waiting for the re-peg that ends `epoch`.
    struct Pending {
        uint128 amount0;
        uint128 amount1;
        uint64 epoch;
    }

    /// @notice How an epoch's deposits became shares: their total value at the NAV `answer`, and
    ///         the shares minted for it, which the depositors claim in proportion to their value.
    struct Conversion {
        uint128 answer;
        uint128 value;
        uint256 shares;
    }

    enum Action {
        Deposit,
        Cancel,
        Withdraw,
        Repeg
    }

    int24 public constant TICK_SPACING = 10;
    /// @notice Ticks of the base range on each side of the NAV's tick-spacing interval (1.0001^200 ≈ 2%).
    int24 public constant BASE_TICKS = 200;
    /// @notice Width of the one-sided range for what the base range cannot use (≈ 3%).
    int24 public constant LIMIT_TICKS = 300;
    /// @notice No swap may leave the price more than this many ticks from the NAV's interval (≈ 5%).
    int24 public constant BAND_TICKS = 500;
    /// @notice The swap fee at a fresh NAV and at MAX_NAV_AGE, in hundredths of a basis point.
    uint24 public constant MIN_FEE = 3_000;
    uint24 public constant MAX_FEE = 10_000;
    uint256 public constant MAX_NAV_AGE = 1 hours;
    /// @notice How far past its block a record's time may run, as Ganymede's evidence checks allow
    ///         for clocks; such a record counts as fresh.
    uint256 public constant CLOCK_TOLERANCE = 60;
    /// @notice Shares locked for good by the first deposit.
    uint256 public constant MINIMUM_SHARES = 1_000;

    bytes32 private constant BASE_SALT = bytes32(0);
    bytes32 private constant LIMIT_SALT = bytes32(uint256(1));

    IPoolManager public immutable poolManager;
    IRwaNavFeed public immutable navFeed;
    address public immutable asset;
    address public immutable dollar;
    Currency public immutable currency0;
    Currency public immutable currency1;
    bool public immutable assetIsCurrency0;
    PoolId public immutable poolId;
    uint8 public immutable decimals;
    /// @notice The smallest first deposit, $10 in dollar-token units.
    uint256 public immutable minFirstDeposit;
    // 10^(feed decimals + asset decimals) and 10^(dollar decimals): the feed's answer times
    // dollarUnit / navUnit is the price of one base unit of the asset in dollar-token base units.
    uint256 private immutable navUnit;
    uint256 private immutable dollarUnit;

    string public name;
    string public symbol;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    Range public baseRange;
    Range public limitRange;
    /// @notice ERC-6909 claims held for liquidity providers outside the ranges, per currency.
    uint256 public idle0;
    uint256 public idle1;
    /// @notice The `updatedAt` of the NAV record the ranges are centred on.
    uint256 public peggedAt;
    uint160 public bandLowerSqrtPriceX96;
    uint160 public bandUpperSqrtPriceX96;
    /// @notice The number of re-pegs so far. Deposits made in an epoch become shares at the re-peg
    ///         that ends it.
    uint256 public epoch;
    /// @notice Deposits waiting for the next re-peg, per currency; part of the idle claims but not of
    ///         the holdings the shares own.
    uint256 public pending0;
    uint256 public pending1;
    mapping(address => Pending) public pendingOf;
    mapping(uint256 => Conversion) public conversions;
    uint256 private _locked = 1;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);
    event Deposited(address indexed account, uint256 indexed epoch, uint256 amount0, uint256 amount1);
    event DepositCancelled(address indexed account, uint256 indexed epoch, uint256 amount0, uint256 amount1);
    event Converted(uint256 indexed epoch, uint256 navAnswer, uint256 value, uint256 shares);
    event SharesClaimed(address indexed account, uint256 indexed epoch, uint256 shares);
    event Withdrawn(address indexed account, uint256 shares, uint256 amount0, uint256 amount1);
    event Repegged(
        uint256 indexed navUpdatedAt,
        uint256 navAnswer,
        uint160 sqrtPriceX96,
        int24 baseLower,
        int24 baseUpper,
        uint128 baseLiquidity,
        int24 limitLower,
        int24 limitUpper,
        uint128 limitLiquidity
    );

    error NotPoolManager();
    error HookNotImplemented();
    error PoolOpenedByHook();
    error LiquidityThroughHook();
    error InvalidAddress();
    error InvalidToken();
    error InvalidAmount();
    error BelowMinimum();
    error Expired();
    error SlippageExceeded();
    error NoLiquidity();
    error NothingToCancel();
    error NavUnavailable();
    error NavTooOld(uint256 updatedAt);
    error NavInFuture(uint256 updatedAt);
    error NavOutOfRange();
    error OutsideBand(uint160 sqrtPriceX96);
    error InsufficientBalance();
    error InsufficientAllowance();
    error TransferFailed();
    error Reentrancy();

    modifier onlyPoolManager() {
        if (msg.sender != address(poolManager)) revert NotPoolManager();
        _;
    }

    modifier nonReentrant() {
        if (_locked != 1) revert Reentrancy();
        _locked = 2;
        _;
        _locked = 1;
    }

    modifier beforeDeadline(uint256 deadline) {
        if (block.timestamp > deadline) revert Expired();
        _;
    }

    /// @dev Deploy at an address whose low bits carry exactly these permissions (a CREATE2 salt).
    constructor(
        address manager,
        address assetToken,
        address dollarToken,
        address feed,
        string memory shareName,
        string memory shareSymbol
    ) {
        if (manager == address(0) || feed == address(0)) revert InvalidAddress();
        if (assetToken == address(0) || dollarToken == address(0) || assetToken == dollarToken) revert InvalidAddress();
        Hooks.validateHookPermissions(
            IHooks(address(this)),
            Hooks.Permissions({
                beforeInitialize: true,
                afterInitialize: false,
                beforeAddLiquidity: true,
                afterAddLiquidity: false,
                beforeRemoveLiquidity: false,
                afterRemoveLiquidity: false,
                beforeSwap: true,
                afterSwap: true,
                beforeDonate: false,
                afterDonate: false,
                beforeSwapReturnDelta: false,
                afterSwapReturnDelta: false,
                afterAddLiquidityReturnDelta: false,
                afterRemoveLiquidityReturnDelta: false
            })
        );
        // Dollar tokens have 6 to 18 decimals; fewer would leave a $10 first deposit too few units.
        uint256 dollarDecimals = IRwaPoolToken(dollarToken).decimals();
        uint256 priceDecimals = uint256(IRwaNavFeed(feed).decimals()) + IRwaPoolToken(assetToken).decimals();
        if (dollarDecimals < 6 || dollarDecimals > 18 || priceDecimals > 36) revert InvalidToken();

        poolManager = IPoolManager(manager);
        navFeed = IRwaNavFeed(feed);
        asset = assetToken;
        dollar = dollarToken;
        bool assetFirst = assetToken < dollarToken;
        assetIsCurrency0 = assetFirst;
        currency0 = Currency.wrap(assetFirst ? assetToken : dollarToken);
        currency1 = Currency.wrap(assetFirst ? dollarToken : assetToken);
        decimals = uint8(dollarDecimals);
        dollarUnit = 10 ** dollarDecimals;
        navUnit = 10 ** priceDecimals;
        minFirstDeposit = 10 * 10 ** dollarDecimals;
        name = shareName;
        symbol = shareSymbol;

        PoolKey memory key = poolKey();
        poolId = key.toId();
        (uint160 sqrtPriceX96, uint256 updatedAt, ) = _nav();
        poolManager.initialize(key, sqrtPriceX96);
        _setPeg(_center(sqrtPriceX96), updatedAt);
    }

    // ---- Liquidity providers ----

    /// @notice Deposits up to `amount0Max` of currency0 and `amount1Max` of currency1 (both approved
    ///         to this contract) at the ratio the hook holds the two tokens, taking only what that
    ///         ratio needs. The deposit waits for the first NAV record published after it: the re-peg
    ///         to that record puts it to work and mints its shares, valuing it and the holdings at
    ///         that NAV, and `claimShares` pays them out (`withdraw` and the next `deposit` claim
    ///         first). Until then `cancelDeposit` returns it. A fresh record the pool has not re-pegged
    ///         to yet is applied first, so a deposit cannot become liquidity just before trades its
    ///         depositor can already see, and while the latest record is dated ahead of the chain's
    ///         clock deposits revert until it can be. A maximum above 2^128 - 1 counts as that, so
    ///         `type(uint256).max` lets the other token decide. The first deposit instead takes both
    ///         amounts in full, needs a fresh NAV, mints their value at the NAV in dollar-token units
    ///         as shares at once and opens the ranges; `shares` is 0 for every later deposit.
    function deposit(uint256 amount0Max, uint256 amount1Max, uint256 deadline)
        external
        nonReentrant
        beforeDeadline(deadline)
        returns (uint256 shares, uint256 amount0, uint256 amount1)
    {
        _claim(msg.sender);
        bytes memory result = poolManager.unlock(abi.encode(Action.Deposit, msg.sender, amount0Max, amount1Max));
        (shares, amount0, amount1) = abi.decode(result, (uint256, uint256, uint256));
    }

    /// @notice Returns the caller's deposit that is still waiting for the next NAV record.
    function cancelDeposit() external nonReentrant returns (uint256 amount0, uint256 amount1) {
        bytes memory result = poolManager.unlock(abi.encode(Action.Cancel, msg.sender, uint256(0), uint256(0)));
        (amount0, amount1) = abi.decode(result, (uint256, uint256));
    }

    /// @notice Pays `account` the shares its deposit became at a re-peg. Anyone can call it.
    function claimShares(address account) external nonReentrant returns (uint256 shares) {
        return _claim(account);
    }

    /// @notice Burns `shares` and pays their part of the ranges and of the idle claims, fees
    ///         included. Works with any NAV, stale or missing. Claims the caller's converted deposit
    ///         first.
    function withdraw(uint256 shares, uint256 amount0Min, uint256 amount1Min, uint256 deadline)
        external
        nonReentrant
        beforeDeadline(deadline)
        returns (uint256 amount0, uint256 amount1)
    {
        if (shares == 0) revert InvalidAmount();
        _claim(msg.sender);
        bytes memory result = poolManager.unlock(abi.encode(Action.Withdraw, msg.sender, shares, uint256(0)));
        (amount0, amount1) = abi.decode(result, (uint256, uint256));
        if (amount0 < amount0Min || amount1 < amount1Min) revert SlippageExceeded();
        emit Withdrawn(msg.sender, shares, amount0, amount1);
    }

    /// @notice Re-pegs the pool to a NAV record newer than `peggedAt`; the first swap after a record
    ///         does the same. Anyone can call it. Returns false when there is no newer record.
    function repeg() external nonReentrant returns (bool repegged) {
        return abi.decode(poolManager.unlock(abi.encode(Action.Repeg, address(0), uint256(0), uint256(0))), (bool));
    }

    function unlockCallback(bytes calldata data) external onlyPoolManager returns (bytes memory) {
        (Action action, address account, uint256 a, uint256 b) = abi.decode(data, (Action, address, uint256, uint256));
        if (action == Action.Deposit) {
            (uint256 shares, uint256 amount0, uint256 amount1) = _deposit(account, a, b);
            return abi.encode(shares, amount0, amount1);
        }
        if (action == Action.Cancel) {
            (uint256 amount0, uint256 amount1) = _cancel(account);
            return abi.encode(amount0, amount1);
        }
        if (action == Action.Withdraw) {
            (uint256 amount0, uint256 amount1) = _withdraw(account, a);
            return abi.encode(amount0, amount1);
        }
        (uint160 sqrtPriceX96, uint256 updatedAt, uint256 answer) = _nav();
        if (updatedAt == peggedAt) return abi.encode(false);
        _repeg(sqrtPriceX96, updatedAt, answer);
        return abi.encode(true);
    }

    // ---- Hook callbacks ----

    /// @dev The hook opens its one pool itself, in the constructor.
    function beforeInitialize(address, PoolKey calldata, uint160) external pure returns (bytes4) {
        revert PoolOpenedByHook();
    }

    /// @dev Only the hook adds liquidity, and the pool manager does not call it back for its own calls.
    function beforeAddLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert LiquidityThroughHook();
    }

    /// @dev Needs a NAV at most MAX_NAV_AGE old, re-pegs first when the NAV record is newer than
    ///      the ranges, and sets the fee for the NAV's age.
    function beforeSwap(address, PoolKey calldata, SwapParams calldata, bytes calldata)
        external
        onlyPoolManager
        returns (bytes4, BeforeSwapDelta, uint24)
    {
        if (_locked != 1) revert Reentrancy();
        (uint160 sqrtPriceX96, uint256 updatedAt, uint256 answer) = _nav();
        if (updatedAt != peggedAt) _repeg(sqrtPriceX96, updatedAt, answer);
        return (IHooks.beforeSwap.selector, BeforeSwapDeltaLibrary.ZERO_DELTA, _fee(updatedAt) | LPFeeLibrary.OVERRIDE_FEE_FLAG);
    }

    function afterSwap(address, PoolKey calldata, SwapParams calldata, BalanceDelta, bytes calldata)
        external
        view
        onlyPoolManager
        returns (bytes4, int128)
    {
        (uint160 sqrtPriceX96, , , ) = poolManager.getSlot0(poolId);
        if (sqrtPriceX96 < bandLowerSqrtPriceX96 || sqrtPriceX96 > bandUpperSqrtPriceX96) revert OutsideBand(sqrtPriceX96);
        return (IHooks.afterSwap.selector, 0);
    }

    function afterInitialize(address, PoolKey calldata, uint160, int24) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterAddLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata)
        external
        pure
        returns (bytes4, BalanceDelta)
    {
        revert HookNotImplemented();
    }

    function beforeRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, bytes calldata)
        external
        pure
        returns (bytes4)
    {
        revert HookNotImplemented();
    }

    function afterRemoveLiquidity(address, PoolKey calldata, ModifyLiquidityParams calldata, BalanceDelta, BalanceDelta, bytes calldata)
        external
        pure
        returns (bytes4, BalanceDelta)
    {
        revert HookNotImplemented();
    }

    function beforeDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
    }

    function afterDonate(address, PoolKey calldata, uint256, uint256, bytes calldata) external pure returns (bytes4) {
        revert HookNotImplemented();
